#!/usr/bin/env node
// Builds ui/prototype/js/track-geometry.generated.js from the authored track geometry, so the prototype draws the
// same control points the simulation uses. Plain node, no dependencies.
//
//   node ui/prototype/tools/build-track-geometry.mjs           write the generated file
//   node ui/prototype/tools/build-track-geometry.mjs --check   exit 1 if the committed file is stale
//
// Inputs:  data/authored/tracks/geometry/<layout_id>.json  (the format the track editor reads and writes)
//          data/authored/tracks/circuits.json              (circuit name and length_km per layout)
// Output:  ui/prototype/js/track-geometry.generated.js     (committed; the prototype opens by double click, so it
//                                                           cannot fetch the JSON at run time)
// Full validation (length against circuits.json, self-intersection, spacing, corners) is the backend's job:
//   dotnet run --project tools/Paddock.DataPipeline -- validate-authored
// This tool only refuses input it cannot turn into a drawing.

import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
export const REPO_ROOT = join(here, '..', '..', '..');
export const OUTPUT = join(REPO_ROOT, 'ui', 'prototype', 'js', 'track-geometry.generated.js');

const HEADER = `/* GENERATED by ui/prototype/tools/build-track-geometry.mjs from data/authored/tracks/geometry/*.json.
 * Do not edit by hand: edit the JSON (or use the track editor), then run
 *   node ui/prototype/tools/build-track-geometry.mjs
 * Points are control points in metres (x east, y north), point 0 on the start line.
 * corners: [control point index, name]. */
`;

/* Returns the text of the generated file for a repo root. */
export function build(root = REPO_ROOT) {
  const dir = join(root, 'data', 'authored', 'tracks', 'geometry');
  const circuits = JSON.parse(readFileSync(join(root, 'data', 'authored', 'tracks', 'circuits.json'), 'utf8'));
  const info = new Map();
  for (const c of circuits.circuits) for (const l of c.layouts) info.set(l.layout_id, { name: c.name, lengthKm: l.length_km });

  const files = readdirSync(dir).filter(f => f.endsWith('.json')).sort();
  const entries = [];
  for (const f of files) {
    const g = JSON.parse(readFileSync(join(dir, f), 'utf8'));
    const where = `${f}`;
    if (g.layout_id + '.json' !== f) throw new Error(`${where}: file name must be <layout_id>.json (layout_id is "${g.layout_id}")`);
    const meta = info.get(g.layout_id);
    if (!meta) throw new Error(`${where}: layout "${g.layout_id}" is not in circuits.json`);
    const pts = g.control_points;
    if (!Array.isArray(pts) || pts.length < 8 || !pts.every(p => Array.isArray(p) && p.length === 2 && p.every(Number.isFinite))) {
      throw new Error(`${where}: control_points must be a list of at least 8 [x, y] pairs`);
    }
    const corners = (g.corners || []).map(c => {
      if (!Number.isInteger(c.point) || c.point < 0 || c.point >= pts.length || !c.name) throw new Error(`${where}: bad corner ${JSON.stringify(c)}`);
      return [c.point, c.name];
    });
    const body = { name: meta.name, lengthKm: meta.lengthKm, source: g.source, points: pts, corners };
    entries.push(`${JSON.stringify(g.layout_id)}: ${JSON.stringify(body)}`);
  }
  return `${HEADER}globalThis.TRACK_GEOMETRY = {\n${entries.map(e => '  ' + e).join(',\n')}\n};\n`;
}

const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (isMain) {
  const text = build();
  if (process.argv.includes('--check')) {
    const current = existsSync(OUTPUT) ? readFileSync(OUTPUT, 'utf8') : '';
    if (current !== text) {
      console.error('track-geometry.generated.js is stale. Run: node ui/prototype/tools/build-track-geometry.mjs');
      process.exit(1);
    }
    console.log('track-geometry.generated.js is up to date.');
  } else {
    writeFileSync(OUTPUT, text);
    console.log(`Wrote ${OUTPUT.replace(REPO_ROOT + '/', '')} (${(text.match(/^  "/gm) || []).length} layouts).`);
  }
}
